mapper.select:
SELECT e.id, e.entry_code, e.entry_type, e.erp_po_no, e.mes_work_order_no, e.consignor_id, e.batch_number, e.total_count, e.predicted_arrival_time, e.warehouse_id, e.damage_count, e.surpass_count, e.over_receive_audit_status, e.status, e.lack_count, e.wait_supplement_flag, e.create_time, e.create_by, e.update_time, e.update_by, w.name AS warehouse_name, w.warehouse_type AS warehouse_type, c.customer_name AS consignor_name, (SELECT COUNT(*) FROM wms_warehousing_entry_details d WHERE d.warehousing_entry_id = e.id AND d.is_del = 1) AS detail_rows, (SELECT IFNULL(SUM(d.count), 0) FROM wms_warehousing_entry_details d WHERE d.warehousing_entry_id = e.id AND d.is_del = 1) AS plan_count, (SELECT IFNULL(SUM(d.received_count), 0) FROM wms_warehousing_entry_details d WHERE d.warehousing_entry_id = e.id AND d.is_del = 1) AS received_total, (SELECT IFNULL(SUM(u.count), 0) FROM wms_warehousing_entry_up u WHERE u.warehousing_entry_id = e.id AND u.status = 2 AND u.is_del = 1) AS putaway_total FROM wms_warehousing_entry e LEFT JOIN wms_warehouse w ON w.id = e.warehouse_id LEFT JOIN wms_customer c ON c.id = e.consignor_id WHERE e.is_del = 1
AND e.entry_code LIKE CONCAT('%', #{q.entryCode}, '%')
AND e.entry_type = #{q.entryType}
AND e.warehouse_id = #{q.warehouseId}
AND e.consignor_id = #{q.consignorId}
AND e.batch_number LIKE CONCAT('%', #{q.batchNumber}, '%')
AND e.mes_work_order_no LIKE CONCAT('%', #{q.mesWorkOrderNo}, '%')
AND e.erp_po_no LIKE CONCAT('%', #{q.erpPoNo}, '%')
AND e.status = #{q.status}
AND e.status NOT IN (60, 99)
ORDER BY e.create_time DESC, e.id DESC
